<?php require_once __DIR__ . '/lib/admin_schema.php'; $currentAdmin = adminGuard(); $pageTitle='سفارشات'; include __DIR__.'/includes/header.php'; ?>
<div class="card"><div class="card-header"><h2>سفارشات</h2></div><div class="card-body"><p>لیست سفارشات از ماژول اصلی سفارش خوانده می‌شود.</p><?php $db=Database::getInstance()->getConnection(); $stmt=$db->prepare('SELECT * FROM orders ORDER BY created_at DESC LIMIT 50'); $stmt->execute(); $rows=$stmt->fetchAll(); ?><table class="table"><tr><th>شماره</th><th>مشتری</th><th>موبایل</th><th>مبلغ</th><th>وضعیت</th><th>تاریخ</th></tr><?php foreach($rows as $r): ?><tr><td><?=h($r['order_number'])?></td><td><?=h($r['customer_name'])?></td><td><?=h($r['customer_phone'])?></td><td><?=h(number_format((float)$r['total']))?></td><td><?=h($r['order_status'])?></td><td><?=h(formatJalaliDateTime($r['created_at']))?></td></tr><?php endforeach; ?></table></div></div><?php include __DIR__.'/includes/footer.php'; ?>
